import { nativeExecutable } from '../scripts/native-paths.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const credit =
  'Skeleton generated by ESPresso, a tool made by James Platt for Manchester Stinger Motorsports';
const puns = new Set([
  'This code tastes like coffee!',
  'May your coffee be strong and your latency low.',
  'Grounds for a great project.',
  'Brewed to run',
  'A latte tasks, only 1 chip',
  'Bean there, built that.',
  'A fresh pot of parallel problems',
  'Every task deserves a coffee break.',
  'This project has bean brewing.',
  'Bean busy making tasks.',
  'A little chip with a latte potential.',
  'Wake up and smell the semaphores (and coffee)',
]);
const call = (request) =>
  JSON.parse(
    execFileSync(nativeExecutable(), [], {
      input: JSON.stringify(request),
      encoding: 'utf8',
      windowsHide: true,
      maxBuffer: 24 * 1024 * 1024,
    }),
  );
const request = (value) => {
  const response = call(value);
  assert.equal(response.ok, true, response.error);
  return response.result;
};
const project = () => ({
  version: 1,
  name: 'coffee-node',
  target: 'esp32s3',
  nodes: Array.from({ length: 24 }, (_, i) => ({
    id: randomUUID(),
    kind: 'task',
    name: `Task ${i}`,
    symbol: `worker${i}`,
    position: { x: i * 270, y: 0 },
    periodMs: 100,
    priority: 2,
    stackBytes: 4096,
    core: 'any',
    libraryIds: ['sensor'],
    setup: [],
    loop: [],
  })),
  libraries: [
    {
      id: 'sensor',
      name: 'Sensor',
      source: 'local',
      version: 'local',
      headers: ['Sensor.hpp'],
      dependencies: [],
      files: { 'Sensor.hpp': '#pragma once\n// Third-party library.\n' },
    },
  ],
});
const exportTo = (p) =>
  request({
    op: 'export',
    project: p,
    path: fs.mkdtempSync(path.join(os.tmpdir(), 'espresso-coffee-')),
  }).path;

test('generated files carry the credit, with stable coffee puns only on task sources', () => {
  const p = project();
  const first = request({ op: 'preview', project: p });
  assert.equal(first.valid, true);
  const seen = new Set();
  for (const [name, text] of Object.entries(first.files)) {
    if (name.startsWith('components/')) continue;
    if (name === '.vscode/settings.json') {
      assert.ok(text.startsWith('//' + credit + '\n\n'), name);
      assert.equal(
        JSON.parse(text.slice(text.indexOf('{')))[
          'C_Cpp.default.compileCommands'
        ],
        '${workspaceFolder}/build/compile_commands.json',
      );
      continue;
    }
    if (name.endsWith('.json')) {
      assert.equal(JSON.parse(text).generatorCredit, credit, name);
      continue;
    }
    if (/^main\/tasks\/.*_task\.cpp$/.test(name)) {
      const [pun, attribution, separator] = text.split('\n');
      assert.ok(puns.has(pun.slice(2)), name);
      assert.equal(attribution, '//' + credit, name);
      assert.equal(separator, '', name);
      seen.add(pun);
    } else {
      const prefix = /\.(cpp|hpp|h)$/.test(name)
        ? '//' + credit
        : name.endsWith('.md')
          ? '<!--' + credit + '-->'
          : '#' + credit;
      assert.ok(text.startsWith(prefix + '\n\n'), name);
    }
  }
  assert.ok(seen.size > 1, 'Different random task IDs select different puns');
  assert.deepEqual(request({ op: 'preview', project: p }).files, first.files);
  assert.equal(
    first.files['components/Sensor/Sensor.hpp'],
    p.libraries[0].files['Sensor.hpp'],
  );
  const output = exportTo(p);
  const manifest = JSON.parse(
    fs.readFileSync(path.join(output, 'espresso.project.json'), 'utf8'),
  );
  assert.equal(manifest.generatorCredit, credit);
  for (const [name, text] of Object.entries(first.files))
    assert.equal(fs.readFileSync(path.join(output, name), 'utf8'), text, name);
  const sourceName = 'main/tasks/worker0_task.cpp';
  const handwritten =
    first.files[sourceName] + '\n// My board implementation.\n';
  fs.writeFileSync(path.join(output, sourceName), handwritten);
  const imported = request({
    op: 'import-project',
    path: path.join(output, 'espresso.project.json'),
  }).project;
  const second = exportTo(imported);
  assert.equal(
    fs.readFileSync(path.join(second, sourceName), 'utf8'),
    handwritten,
  );
  assert.equal(handwritten.split(credit).length - 1, 1);
});

test('skeleton keeps task comments concise and identifies generated support', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  const preview = request({ op: 'preview', project: p });
  const task = preview.files['main/tasks/worker0_task.cpp'];
  assert.doesNotMatch(
    task,
    /ESPresso: USER|Implement task logic here|Add .* below/,
  );
  assert.match(task, /\/\/ Runs once\.\nvoid setup\(\)/);
  assert.match(task, /\/\/ Runs repeatedly\.\nvoid loop\(\)/);
  assert.match(preview.files['main/tasks/worker0_task.hpp'], /GENERATED FILE/);
  assert.match(
    preview.files['main/generated/task_runtime.cpp'],
    /GENERATED FILE/,
  );
  assert.match(preview.files['README.md'], /Where to edit/);
  assert.match(preview.files['README.md'], /early return skips end connectors/);
  const folder = exportTo(p);
  const manifestPath = path.join(folder, 'espresso.project.json');
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const strip = (text) =>
    text
      .split(/(?<=\n)/)
      .filter((line) => !/^\s*(?:\/\/|#) ESPresso: /.test(line))
      .join('');
  for (const [name, entry] of Object.entries(manifest.files)) {
    if (!entry.generated || !/\.(?:cpp|hpp|h|cmake|txt)$/.test(name)) continue;
    entry.generated = strip(entry.generated);
    fs.writeFileSync(
      path.join(folder, name),
      strip(fs.readFileSync(path.join(folder, name), 'utf8')),
    );
  }
  fs.writeFileSync(manifestPath, JSON.stringify(manifest));
  const imported = request({ op: 'import-project', path: folder }).project;
  const again = request({ op: 'preview', project: imported });
  assert.equal(again.valid, true, JSON.stringify(again.diagnostics));
  assert.equal(again.files['main/tasks/worker0_task.cpp'], strip(task));
});

test('edited generated code is rejected during import', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  const output = exportTo(p);
  fs.appendFileSync(
    path.join(output, 'main/generated/task_runtime.cpp'),
    '\nvoid unexpected_edit() {}\n',
  );
  const rejected = call({
    op: 'import-project',
    path: path.join(output, 'espresso.project.json'),
  });
  assert.equal(rejected.ok, false);
  assert.match(rejected.error, /generated file changed/);
});

test('VS Code settings stay editable and survive repeated project imports', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  let output = exportTo(p);
  const edited =
    '// My workspace preferences\n{\n  "editor.tabSize": 4,\n  "C_Cpp.default.compileCommands": "${workspaceFolder}/build/compile_commands.json"\n}\n';
  fs.writeFileSync(path.join(output, '.vscode/settings.json'), edited);
  for (let i = 0; i < 2; i++) {
    const imported = request({
      op: 'import-project',
      path: path.join(output, 'espresso.project.json'),
    }).project;
    output = exportTo(imported);
    assert.equal(
      fs.readFileSync(path.join(output, '.vscode/settings.json'), 'utf8'),
      edited,
    );
  }
});

test('only the corrected CMake include is accepted on import', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  const output = exportTo(p),
    file = path.join(output, 'main/CMakeLists.txt');
  const original = fs.readFileSync(file, 'utf8');
  for (const old of [
    'include("generated/project.cmake")',
    'include(generated/project.cmake)',
  ]) {
    fs.writeFileSync(
      file,
      original.replace(
        'include("${CMAKE_CURRENT_LIST_DIR}/generated/project.cmake")',
        old,
      ),
    );
    const rejected = call({
      op: 'import-project',
      path: path.join(output, 'espresso.project.json'),
    });
    assert.equal(rejected.ok, false);
    assert.match(
      rejected.error,
      /use include\("\$\{CMAKE_CURRENT_LIST_DIR\}\/generated\/project\.cmake"\)/,
    );
  }
  fs.writeFileSync(file, original);
  assert.ok(
    request({
      op: 'import-project',
      path: path.join(output, 'espresso.project.json'),
    }).project,
  );
});

test('placeholder comments use one TODO heading, wrapped notes and preserve supplied code', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  const task = p.nodes[0];
  task.setup = [
    {
      id: 'read',
      kind: 'placeholder',
      name: 'Read pressure',
      note:
        'Read the sensor and populate the pressure sample before publishing it. '.repeat(
          4,
        ) + '\n\nKeep the sample valid only when the sensor reports success.',
    },
  ];
  task.loop = [
    {
      id: 'implemented',
      kind: 'placeholder',
      name: 'Process sample',
      note: 'This note should not be repeated above an implementation.',
    },
    { id: 'empty', kind: 'placeholder', name: 'Store result', note: '' },
  ];
  const body =
    '    const int result = 7; // My exact formatting.\n    (void)result;\n';
  p.code = { [`step-${Buffer.from('implemented').toString('hex')}`]: body };
  const preview = request({ op: 'preview', project: p });
  const source = preview.files[`main/tasks/${task.symbol}_task.cpp`];
  assert.match(
    source,
    /    \/\/ TODO: Read pressure\n    \/\/ Read the sensor/,
  );
  assert.match(source, /    \/\/\n    \/\/ Keep the sample valid/);
  assert.equal((source.match(/TODO: Read pressure/g) ?? []).length, 1);
  assert.doesNotMatch(
    source,
    /TODO: Process sample|TODO: Implement this step|This note should not/,
  );
  assert.ok(source.includes('    // Process sample\n' + body));
  assert.match(source, /    \/\/ TODO: Store result\n/);
  for (const line of source
    .split('\n')
    .filter((line) => line.startsWith('    //')))
    assert.ok(line.length <= 96, line);
});
